import{_ as s,l as n,o as e,c as l,v as t,p as o,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"渐进类型","description":"","frontmatter":{"title":"渐进类型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gradual-typing.md","filePath":"cs/gradual-typing.md","lastUpdated":1789023840000}'),h={name:"cs/gradual-typing.md"};function m(u,a,T,_,A,E){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="渐进类型" tabindex="-1">渐进类型 <a class="header-anchor" href="#渐进类型" aria-label="Permalink to &quot;渐进类型&quot;">​</a></h1><div class="epigraph"><p>未知类型 $\\star$（或 `Any`）与静态类型在同一程序里共存；交界处插入强制，运行时检查，静态侧仍要保持Blame 可追踪。</p><footer>—— 据 Siek and Taha, Gradual Typing, 2006；Tobin-Hochstadt and Felleisen, Interlanguage Migration；Pierce TAPL 对照整理</footer></div><p>上一课<a href="/cs/effect-systems">效应</a>假定类型已知。缺口是<strong>部分注解</strong>：TypeScript、Typed Racket 让未注的部分当 \\(\\star\\)，注了的部分走 STLC/HM。一致性（consistency）\\(\\sim\\) 不是 \\(\\lt :\\)：\\(\\star\\sim\\tau\\) 对任意 \\(\\tau\\)。本课钉强制与 blame，不把 TypeScript 的 <code>any</code> 逃逸当健全样本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全静态拒绝无注解；全动态无静态保证。渐进：检查已知部分，未知部分推迟。强制 <code>⟨τ⇐σ⟩</code> 在运行时验证。缺口是<strong>一致性关系与插入点</strong>，不是再写 W。</p><p>健全渐进：失败时 blame 指向打破契约的那一侧（已注解模块或未注解模块）。不健全（把 <code>any</code> 当静音逃逸）则静态承诺可被绕过。</p><h3 id="不是-hm-的新鲜" tabindex="-1">\\(\\star\\) 不是 HM 的新鲜 \\(\\alpha\\) <a class="header-anchor" href="#不是-hm-的新鲜" aria-label="Permalink to &quot;$\\star$ 不是 HM 的新鲜 $\\alpha$&quot;">​</a></h3><p>\\(\\alpha\\) 须合一到具体类型或量化；\\(\\star\\) 永远可通过。把二者混淆会让「推导成功」变成「什么都没查」。</p><p><span class="marginnote">Siek–Taha 2006。Findler–Felleisen 的高阶契约是 blame 的前身。本课不写所有逐渐类型变体（transient vs guarded）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>双向检查：已知期望类型则检验，未知则合成 \\(\\star\\) 或从语法合成。插入强制：函数强制是包装，参数逆变方向。实现：guarded 在边界包 proxy；transient 在使用处检查形状。</p>',11)),(e(),o(c,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%B7%B2%E6%B3%A8%E8%A7%A3%22%5D%20--%3E%20ST%5B%22%E9%9D%99%E6%80%81%E8%A7%84%E5%88%99%22%5D%0A%20%20UN%5B%22%E6%9C%AA%E6%B3%A8%E8%A7%A3%22%5D%20--%3E%20STAR%5B%22%E2%98%85%22%5D%0A%20%20ST%20--%3E%20CST%5B%22%E4%B8%80%E8%87%B4%E6%80%A7%20~%22%5D%0A%20%20STAR%20--%3E%20CST%0A%20%20CST%20--%3E%20CAST%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E5%BC%BA%E5%88%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/subtyping-variance">子类型</a>：渐进常加动态方向的宽化。与泛型擦除：强制可能只查表面标签。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>性能：proxy 改变身份与对象相等；transient 便宜但不捕获所有高阶错误。这是实现权衡，不是「渐进 = 慢」。</p><p>不要把 <code>@ts-ignore</code> 当理论的一部分。效应与渐进：未注解函数可偷偷 IO，效应系统要默认 ε 为全效应或拒绝声称纯。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Python typing 的全部 PEP 列完。后课默认：\\(\\star\\) + 强制 + 可选 blame。下一课类型健全性：把 STLC、渐进、线性的「不会卡在坏状态」收成定理形状。</p><p>也不把 JSON 解析当渐进类型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>渐进：\\(\\star\\sim\\tau\\)，边界强制，静态部分仍检查。</li><li>blame 指向违约方；逃逸式 <code>any</code> 不健全。</li><li>\\(\\star\\) 不是类型变量 \\(\\alpha\\)。</li><li>出处：Siek and Taha, 2006；Findler–Felleisen 契约；对照 Pierce。</li></ul>',9))])}const f=s(h,[["render",m]]);export{S as __pageData,f as default};
